using System;using System.Linq;using UnityEngine;using UnityEditor;using RoadGunner.Editor;
public static class ClearTravelShoulders {public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Stop first");var l=RoadGunnerLevelAuthoring.Current;var p=l.decorationRoot.Find("H · Travel landmarks and shoulder salvage");var axis=Quaternion.Euler(0,45,0);var changes=new[]{new[]{new Vector2(5,38),new Vector2(7,43)},new[]{new Vector2(26,22),new Vector2(26,16)}};foreach(var pair in changes){var old=axis*new Vector3(pair[0].x*2.5f,0,pair[0].y*2.5f);var delta=axis*new Vector3((pair[1].x-pair[0].x)*2.5f,0,(pair[1].y-pair[0].y)*2.5f);foreach(var t in p.Cast<Transform>().Where(t=>Vector3.Distance(t.position,old)<5)){t.position+=delta;PrefabUtility.RecordPrefabInstancePropertyModifications(t);}}RoadGunnerLevelAuthoring.Save(l);return "Two travel wreck groups moved from junction lanes to clear shoulders; navigation rebaked.";}}
